// Builds the interactive ER diagram (Liam ERD) from the migration SQL into
// public/schema-erd, where /backstage/schema/erd iframes it. Same approach as
// arbiter's /schema page. Output is gitignored; next.config.ts calls this on
// every production build and on dev start, so nothing is regenerated by hand.
import { execFileSync } from "node:child_process";
import {
  existsSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const MIGRATIONS = "drizzle";
const OUT = join("public", "schema-erd");

const migrations = () =>
  readdirSync(MIGRATIONS)
    .filter((f) => f.endsWith(".sql"))
    .sort()
    .map((f) => join(MIGRATIONS, f));

function newestMigrationMtime() {
  return Math.max(0, ...migrations().map((f) => statSync(f).mtimeMs));
}

/** Rebuilds unless the output is already newer than every migration file. */
export function buildErd({ force = false } = {}) {
  const index = join(OUT, "index.html");
  if (
    !force &&
    existsSync(index) &&
    statSync(index).mtimeMs > newestMigrationMtime()
  ) {
    return;
  }
  // Liam parses each input file on its own, so an ALTER TABLE ... ADD
  // CONSTRAINT in a later migration can't find its table. Feed it one file.
  const dir = mkdtempSync(join(tmpdir(), "schema-erd-"));
  const schema = join(dir, "schema.sql");
  writeFileSync(
    schema,
    migrations()
      .map((f) => readFileSync(f, "utf8"))
      .join("\n"),
  );
  try {
    execFileSync(
      "pnpm",
      [
        "exec",
        "liam",
        "erd",
        "build",
        "--input",
        schema,
        "--format",
        "postgres",
        "--output-dir",
        OUT,
      ],
      { stdio: "inherit" },
    );
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

if (process.argv[1] && import.meta.url.endsWith(process.argv[1])) {
  buildErd({ force: true });
}
